"""Modular golden-vector definitions for `tests/golden/punarchi_nannool.jsonl`.

Loaded by `tools/generate_punarchi_golden.py` to compile deterministic,
ASCII-escaped JSONL rows with programmatically synced inventory entries.
"""

from __future__ import annotations

import sys
import tomllib
import unicodedata
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from tools.generate_punarchi_golden import build_vector  # noqa: E402

INVENTORY_TOML = ROOT / "lexicon" / "punarchi-nannool-inventory.toml"
CONTRACT_SOURCE = "specs/025-tamil-punarchi/contracts/punarchi.md"


def _load_inventory_by_sutra() -> dict[int, dict[str, Any]]:
    data = tomllib.loads(INVENTORY_TOML.read_text(encoding="utf-8"))
    by_sutra: dict[int, dict[str, Any]] = {}
    for raw in data["sutra"]:
        sutra_num = int(raw["sutra"])
        by_sutra[sutra_num] = {
            "sutra": sutra_num,
            "chapter": raw["chapter"],
            "tier": raw["tier"],
            "executable": bool(raw["executable"]),
            "tva_page": int(raw["tva_page"]),
            "kandigai_sutra": int(raw["kandigai_sutra"]),
            "pm_ref": raw["pm_ref"],
            "summary": raw["summary"],
            "edition_note": raw.get("edition_note"),
        }
    return by_sutra


