def _step(
    sutra: int,
    rule_id: str,
    stage: int,
    transform: str,
    before: str,
    after: str,
) -> dict[str, Any]:
    return {
        "sutra": sutra,
        "rule_id": rule_id,
        "stage": stage,
        "transform": transform,
        "before": before,
        "after": after,
    }


def _join_expected(
    surface: str,
    transform: str,
    steps: list[dict[str, Any]],
    alternatives: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    return {
        "profile": "nannool-v1",
        "surface": surface,
        "transform": transform,
        "steps": steps,
        "alternatives": alternatives or [],
    }


def _alt(
    surface: str,
    transform: str,
    steps: list[dict[str, Any]],
    *,
    required_context: str | None = None,
    optional_variant: bool = True,
    poetic: bool = False,
) -> dict[str, Any]:
    return {
        "surface": surface,
        "transform": transform,
        "steps": steps,
        "required_context": required_context,
        "optional_variant": optional_variant,
        "poetic": poetic,
    }


