def build_all_vectors() -> list[dict[str, Any]]:
    """Return all punarchi golden vectors in deterministic order."""
    return [
        *prereq_and_error_vectors(),
        *uyireeru_vectors(),
        *meyyeeru_vectors(),
        *urupu_and_closed_class_vectors(),
        *context_and_poetic_vectors(),
        *split_and_context_vectors(),
        *convergence_sutra_coverage_vectors(),
        *edge_case_regression_vectors(),
    ]
